1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>arXiv Public Alert Styles — Component Reference</title>
7	  <link rel="stylesheet" href="design-system.css">
8	  <style>
9	    /* ── Page chrome (reference doc only). Mirrors the layout of
10	       internal/alert-styles.html for consistency, using the public
11	       --arxiv- tokens. This page CONSUMES design-system.css — it never
12	       redefines .ds-alert or the status tokens; the rendered alerts and the
13	       value table read straight from the stylesheet. Light/dark follows the
14	       OS, matching the canonical alert tokens (the first dark-aware tokens
15	       on the public side). ── */
16	    *, *::before, *::after { box-sizing: border-box; }
17	
18	    body {
19	      font-family: var(--arxiv-font-sans);
20	      color: var(--arxiv-ink);
21	      background: var(--arxiv-warm-wash);
22	      margin: 0;
23	      font-size: 14px;
24	      line-height: 1.5;
25	    }
26	    .page { max-width: 980px; margin: 0 auto; padding: 48px 28px 80px; }
27	
28	    .back-link { display: inline-block; margin-bottom: 20px; font-size: 13px; color: var(--arxiv-link-blue); text-decoration: none; }
29	    .back-link:hover { text-decoration: underline; }
30	
31	    .page-header { margin-bottom: 44px; padding-bottom: 20px; border-bottom: 3px solid var(--arxiv-open-blue); }
32	    .page-header h1 { font-size: 24px; font-weight: 700; margin: 0 0 6px; }
33	    .page-header p { margin: 0; color: var(--arxiv-grey); font-size: 13px; max-width: 720px; }
34	    .mode-note { margin-top: 10px; font-size: 12px; color: var(--arxiv-grey-ui); }
35	
36	    .section { margin-bottom: 48px; }
37	    .section-title { font-size: 18px; font-weight: 600; margin: 0 0 4px; }
38	    .section-desc { font-size: 13px; color: var(--arxiv-grey); margin: 0 0 20px; max-width: 720px; line-height: 1.55; }
39	
40	    .live-demo { background: #fff; border: 1px solid var(--arxiv-card-grey); border-radius: 8px; padding: 22px; }
41	    .demo-stack > * + * { margin-top: 14px; }
42	    .demo-sub { font-family: var(--arxiv-font-condensed); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--arxiv-grey-ui); margin: 22px 0 10px; }
43	
44	    .token-table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--arxiv-card-grey); border-radius: 8px; overflow: hidden; font-size: 13px; }
45	    .token-table th { background: var(--arxiv-card-grey); text-align: left; padding: 10px 14px; font-family: var(--arxiv-font-condensed); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--arxiv-grey); border-bottom: 1px solid var(--arxiv-card-grey); }
46	    .token-table td { padding: 10px 14px; border-bottom: 1px solid var(--arxiv-card-grey); vertical-align: middle; }
47	    .token-table tr:last-child td { border-bottom: none; }
48	    .token-table td.state-name { font-weight: 700; color: var(--arxiv-grey); background: #faf8f7; white-space: nowrap; }
49	    .swatch { display: inline-block; width: 18px; height: 18px; border-radius: 3px; border: 1px solid rgba(0,0,0,0.18); vertical-align: middle; margin-right: 6px; }
50	    .ratio-pass { font-weight: 700; }
51	    .ratio-fail { font-weight: 700; color: #c62828; }
52	
53	    code { font-family: var(--arxiv-font-mono); font-size: 12px; background: var(--arxiv-card-grey); padding: 2px 6px; border-radius: 3px; white-space: nowrap; }
54	    .code-block { background: var(--arxiv-ink); color: #f0eeec; border-radius: 6px; padding: 14px 16px; font-family: var(--arxiv-font-mono); font-size: 12px; line-height: 1.6; overflow-x: auto; margin: 0; }
55	
56	    .callout { font-size: 13px; color: var(--arxiv-ink); margin-top: 16px; padding: 12px 16px; background: #fff; border: 1px solid var(--arxiv-card-grey); border-left: 4px solid var(--arxiv-open-blue); border-radius: 0 4px 4px 0; line-height: 1.6; }
57	    .callout + .callout { margin-top: 10px; }
58	
59	    /* Dark chrome — OS-driven, matching the canonical alert tokens. */
60	    @media (prefers-color-scheme: dark) {
61	      body { background: #1c1a17; color: #f0eeec; }
62	      .section-title { color: #f0eeec; }
63	      .section-desc, .page-header p { color: #b0aba6; }
64	      .back-link { color: #64b5f6; }
65	      .live-demo { background: #252118; border-color: #3a3530; }
66	      .token-table { background: #252118; border-color: #3a3530; }
67	      .token-table th { background: #302c28; color: #b0aba6; border-color: #3a3530; }
68	      .token-table td { border-color: #3a3530; color: #f0eeec; }
69	      .token-table td.state-name { background: #2a2520; color: #b0aba6; }
70	      .callout { background: #252118; border-color: #3a3530; color: #f0eeec; }
71	      .callout strong { color: #f0eeec; }
72	      code { background: #302c28; color: #f0eeec; }
73	    }
