158	          <p class="demo-sub">With dismiss / single line</p>
159	
160	          <div class="ds-alert ds-alert-success" role="status">
161	            <svg class="ds-alert-icon" viewBox="0 0 24 24" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/></svg>
162	            <div class="ds-alert-content"><p>Link copied to clipboard.</p></div>
163	            <button class="ds-alert-dismiss" aria-label="Dismiss"><svg viewBox="0 0 24 24" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button>
164	          </div>
