  --arxiv-error-bg:        #fdeaea;
  --arxiv-error-border:    #c62828;  /* Danger Red (functional, not Campus Red) */
  --arxiv-error-fg:        #8b0000;  /* 8.6:1 on bg ✓ AAA */
