file.content:
  line-height: 1.6;
  max-width: 900px;
}
footer.ds-site-footer .ds-site-footer-ack a {
  font-size: 0.8125rem; /* 13px */
  color: var(--arxiv-link-blue);
}
footer.ds-site-footer .ds-site-footer-links {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 0.8125rem; /* 13px */
  line-height: 1.8;
  max-width: 900px;
}
footer.ds-site-footer .ds-site-footer-links a {
  font-size: 0.8125rem; /* 13px */
  color: var(--arxiv-grey);
  text-decoration: none;
}
footer.ds-site-footer .ds-site-footer-links a:hover {
  color: var(--arxiv-ink);
  text-decoration: underline;
}
footer.ds-site-footer .ds-site-footer-sep { color: var(--arxiv-border-light); }

/* Two-region grid layout — main column (ack + links) on the left,
   funders column on the right. Flex with wrap, so on narrow viewports
   the funders drop below. */
.ds-site-footer-grid {
  display: flex;
  row-gap: 24px;
  column-gap: 32px;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
}
.ds-site-footer-main {
  flex: 0 1 auto;
  min-width: 280px;
  max-width: 720px;
}
.ds-site-footer-funders {
  flex-shrink: 0;
  text-align: center;
}
.ds-site-ds-site-footer-funders-label {
  font-family: "IBM Plex Sans", -apple-system, sans-serif;
  font-size: 0.875rem; /* 14px */
  font-weight: 600;
  color: var(--arxiv-ink);
  margin-bottom: 12px;
  line-height: 1.4;
}
.ds-site-ds-site-footer-funders-logos {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}
.ds-funder-logo {
  /* content-box so `height: 40px` describes the IMAGE content height,
     not the total box. The page sets `box-sizing: border-box` globally;
     without this override, padding + border would eat into the 40px
     and the logo would render about 30px tall (visibly small vs the
     spinout approved layout). */
  box-sizing: content-box;
  display: block;
  height: 40px;
  width: auto;
  flex-shrink: 0;
  padding: 4px 8px;
  border: 1px solid var(--arxiv-pill-border);
  border-radius: 3px;
}
@media (max-width: 720px) {
  .ds-site-footer-funders { width: 100%; margin-top: 8px; }
}

/* The reader's home institution is named inline in the ack line —
   part of the approved footer design. In production this would be
   populated via IP-matched member-institution lookup; here it's a
   static placeholder showing the visual treatment. */
.ack-member-inline strong { color: var(--arxiv-ink); font-weight: 600; }

/* Legacy V1 hook: a top-of-footer institutional callout was explored
   in spinout's variant 1 mockup but did NOT make it into the approved
   design. Kept hidden in case the variant infrastructure is wanted
   later. */
.member-footer-callout { display: none; }

/*
╔════════════════════════════════════════════════════════════════════╗
║  PROGRESSIVE ENHANCEMENT: no-JS fallbacks                          ║
╚════════════════════════════════════════════════════════════════════╝
  Requirement: the page must be fully readable and every piece of
  content reachable with JavaScript disabled or failed. Scripts add
  conveniences; they never carry content. (Michel Coornaert browses
  with JS off by choice; low-bandwidth readers get it off by
  circumstance; a blocked CDN should never blank a control.)

  Mechanics: a one-line head script adds class="js" to <html>. Styles
  that HIDE content pending a JS reveal are scoped to html.js (see
  .abs-authors-overflow). Controls that DO nothing without JS are
  hidden here so users never face dead buttons. The search control is
  an <a href="/search"> that JS upgrades to open the overlay — without
  JS it simply navigates to the search page. */
html:not(.js) .abs-authors-toggle { display: none; }   /* dead toggle; all authors already shown */
html:not(.js) .abs-cite-copy { display: none; }        /* clipboard requires JS */
html:not(.js) .abs-cite-styles,
html:not(.js) .abs-cite-source { display: none; }      /* switchers dead; APA + BibTeX defaults visible */
html:not(.js) .abs-labs-toggle { display: none; }      /* Labs switches dead; names + info links still work */
html:not(.js) .abs-labs-empty { display: none; }       /* "toggle a tool" prompt is meaningless without JS */

